parameters.functionCode:
const payload = items[0].json;

const contentType = payload.type || 'blog';
const topic = payload.topic;
const outline = payload.outline || [];
const targetAudience = payload.audience || 'developers';
const tone = payload.tone || 'technical';
const length = payload.length || 'medium';

if (!topic) {
  throw new Error('Topic is required');
}

return [{
  json: {
    type: contentType,
    topic,
    outline,
    targetAudience,
    tone,
    length,
    keywords: payload.keywords || [],
    referenceDocs: payload.referenceDocs || []
  }
}];

