parameters.functionCode:
const result = items[0].json;

// Extract final content from agent response
let content = '';
if (result.response) {
  content = result.response;
} else if (result.messages && result.messages.length > 0) {
  const lastMsg = result.messages[result.messages.length - 1];
  content = lastMsg.content || '';
}

// Generate SEO metadata
const seoTitle = content.split('\n')[0].replace(/^#\s*/, '').substring(0, 60);
const seoDescription = content.substring(0, 160).replace(/[#*_`]/g, '').trim() + '...';

return [{
  json: {
    content,
    seo: {
      title: seoTitle,
      description: seoDescription,
      keywords: items[0].json.keywords || []
    },
    meta: {
      generatedAt: new Date().toISOString(),
      topic: items[0].json.topic,
      type: items[0].json.type
    }
  }
}];

const output = items[0].json;

return [{
  json: {
    success: true,
    content: output.content,
    seo: output.seo,
    meta: output.meta,
    // Ready for CMS integration
    cmsReady: {
      title: output.seo.title,
      body: output.content,
      excerpt: output.seo.description,
      tags: output.seo.keywords,
      status: 'draft'
    }
  }
}];
